import {chromium,expect as baseExpect} from '@playwright/test'
import fs from 'node:fs/promises'
const origin=process.env.RELEASE_ORIGIN||'http://127.0.0.1:14003',out=process.env.RELEASE_OUTPUT||'artifacts/energy-release-20260922/preview'
const expect=baseExpect.configure({timeout:25000}),checks=[],errors=[]
const catalog=JSON.parse(await fs.readFile('packages/student-web/src/lib/project-lines/renewable-courses.json'))
await fs.mkdir(out,{recursive:true})
const browser=await chromium.launch({args:['--no-proxy-server']}),page=await browser.newPage({viewport:{width:1440,height:1000}})
page.on('pageerror',e=>errors.push(String(e)))
const work=page.locator('[data-renewable-workspace]')
async function open(id,node='M01'){expect((await page.goto(`${origin}/explore/energy-motion/${id}?node=${node}`)).status()).toBe(200);await expect(work.getByRole('button',{name:'运行并保留这次实验'})).toBeEnabled()}
const run=()=>work.getByRole('button',{name:'运行并保留这次实验'}).click()
async function check(name,fn){await fn();checks.push({name,passed:true});console.log('PASS '+name)}
async function covers(){const images=page.locator('[data-line-detail="energy-motion"] img[src*="cover-engineering-v2"]');await expect(images).toHaveCount(10);for(const image of await images.all()){await image.scrollIntoViewIfNeeded();await expect.poll(()=>image.evaluate(i=>i.complete&&i.naturalWidth>0),{timeout:180000}).toBe(true)}}
try{
 await check('9 项目、10 张新版封面与入口层级',async()=>{await page.goto(origin+'/library?view=lines&line=energy-motion');for(const p of catalog)await expect(page.locator(`[data-project-card="${p.id}"]`)).toBeVisible();await covers();await page.screenshot({path:out+'/energy-line-desktop.png',fullPage:true})})
 await check('三种入口操作、个人发现与刷新恢复',async()=>{for(const [id,label,value] of [['catch-a-sunbeam','面板倾角 / °',45],['tune-a-wind-rotor','叶片安装角 / °',40],['keep-the-beacon-on','可暂停负载 / mW',1]]){await open(id);await run();await page.getByRole('slider',{name:label}).fill(String(value));await run();await page.getByRole('button',{name:'保存我的发现',exact:true}).click();await expect(page.locator('#project-delivery')).toContainText('已交付版本');await page.reload();await expect(page.getByRole('slider',{name:label})).toHaveValue(String(value));await expect(page.locator('#project-delivery')).toContainText('已交付版本')}})
 await check('数字原型快照与实物交付门槛',async()=>{await open('build-a-solar-tracker','M05');await run();await page.getByRole('slider',{name:'面板倾角 / °'}).fill('45');await run();await page.getByLabel('我选择这一版的依据',{exact:true}).fill('发布验证：同负载比较两个角度，选择本次平均输入较高的一版。');await page.getByLabel('这些结果还不能证明什么',{exact:true}).fill('发布验证：只是教学模型，需要实物打印与真实测量。');await page.getByRole('button',{name:'保存数字原型',exact:true}).click();await expect(page.locator('#digital-prototype')).toContainText('已交付版本');await expect(page.getByRole('button',{name:'提交最终作品',exact:true})).toBeDisabled();await page.getByRole('slider',{name:'面板倾角 / °'}).fill('55');await expect(page.getByRole('button',{name:'保存数字原型',exact:true})).toBeDisabled();await page.locator('#digital-prototype > details > summary').filter({hasText:'已交付版本'}).click();await expect(page.locator('#digital-prototype [data-renewable-report]')).toContainText('45°');await page.locator('#digital-prototype').screenshot({path:out+'/prototype.png'})})
 await check('可执行规则、异常诊断与首次挑战记录',async()=>{await open('write-energy-dispatch-rules','M02');await page.getByLabel('我的四行规则').fill('pause = 2.32\nresume = 2.58\nmissing = off\ncontrol = hysteresis');await page.getByRole('button',{name:'应用我的规则'}).click();await expect(page.getByRole('slider',{name:'暂停阈值 / V'})).toHaveValue('2.32');await open('build-a-wind-solar-station','M02');await page.getByLabel('我先怀疑什么').fill('发布验证：先查接收字段单位，确认是否解释成了错误的电压。');await page.getByRole('button',{name:'检查数据接口'}).click();await page.getByLabel('接收端字段单位').selectOption('mV');await work.getByLabel('测试工况').selectOption('unit');await run();await open('run-an-energy-mission','M03');await page.getByLabel('事前任务、条件与停止标准').fill('发布验证：同负载在组合新工况保持关键服务，保留第一次结果。');await page.getByRole('button',{name:'冻结当前方案'}).click();await page.getByRole('button',{name:'打开新工况，保存第一次数字结果'}).click();const first=await page.getByText(/首次关键服务 .* 秒/).innerText();await page.reload();await expect(page.getByRole('button',{name:'第一次数字结果已固定'})).toBeDisabled();await expect(page.getByText(/首次关键服务 .* 秒/)).toHaveText(first)})
 await check('29 节课程正文、资料与打印文件',async()=>{for(const c of catalog.filter(p=>p.kind!=='micro'))for(let i=1;i<=c.learningNodes;i++){await open(c.id,`M${String(i).padStart(2,'0')}`);expect((await page.locator('#lesson-reading').innerText()).length).toBeGreaterThan(300);await expect(page.locator('#lesson-references a').first()).toBeVisible()}for(const file of ['build-guide.html','parts.zip','dispatch.ino','starter-parts.scad'])expect((await page.request.get(origin+'/project-lines/energy-motion/renewable-hardware/'+file)).status()).toBe(200)})
 await check('手机布局、WebGL 降级与既有课程',async()=>{await page.setViewportSize({width:390,height:844});await page.goto(origin+'/library?view=lines&line=energy-motion');await covers();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:out+'/energy-line-mobile.png',fullPage:true});const c=await browser.newContext();await c.addInitScript(()=>{const get=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(type,...args){return String(type).includes('webgl')?null:get.call(this,type,...args)}});const p=await c.newPage();await p.goto(origin+'/explore/energy-motion/catch-a-sunbeam');await expect(p.getByText('二维替代视图 · 参数仍可操作')).toBeVisible();await p.getByRole('button',{name:'运行并保留这次实验'}).click();await expect(p.getByText('平均采集前输入')).toBeVisible();await c.close();for(const route of ['/explore/biomedicine/build-a-candidate-filter?node=M01','/explore/space-exploration/assemble-a-rover?node=M04','/library/molecule-monster-hunter']){expect((await page.goto(origin+route)).status()).toBe(200);expect(await page.locator('body').innerText()).not.toContain('Application error')}expect((await page.request.get(origin+'/api/health')).status()).toBe(200);expect((await page.request.get(origin+'/api/learning/records?library_slug=catch-a-sunbeam&module_id=WORK&activity_id=renewable-work&kind=classroom&content_version=1.0')).status()).toBe(401)})
 expect(errors).toEqual([])
 await fs.writeFile(out+'/verification.json',JSON.stringify({origin,passed:true,checks,errors,checkedAt:new Date().toISOString(),scope:'匿名浏览器验证；未向生产写入学生作业；账号隔离已在本地验证。'},null,2))
}catch(e){await page.screenshot({path:out+'/failure.png',fullPage:true}).catch(()=>{});await fs.writeFile(out+'/verification.json',JSON.stringify({origin,passed:false,checks,errors,failure:String(e)},null,2));throw e}finally{await browser.close()}
